/* TAGCOUNT: Maximum tags supported (matches AwesomeWM limit of 32)
 * This is an architectural constant tied to uint32_t tag bitmasks.
 * Tags are created in Lua via awful.tag - this just defines the upper limit. */
#define TAGCOUNT (32)

