awesome_restart(void)
{
    awesome_atexit(true);
    execvp(globalconf.argv[0], globalconf.argv);
    /* If we get here, exec failed */
    warn("restart failed: execvp(%s) failed: %s", globalconf.argv[0], strerror(errno));
}

