4913→void
4914→swapstack(const Arg *arg)
4915→{
4916→	Client *sel = focustop(selmon);
4917→	int sel_idx = -1;
4918→	int target_idx = -1;
4919→	int i;
4920→	Client *tmp;
4921→	lua_State *L;
4922→
4923→	if (!sel)
4924→		return;
4925→
4926→	if (globalconf.clients.len < 2)
4927→		return;
4928→
4929→	/* Find sel's position in clients array */
4930→	for (i = 0; i < globalconf.clients.len; i++) {
4931→		if (globalconf.clients.tab[i] == sel) {
4932→			sel_idx = i;
4933→			break;
4934→		}
4935→	}
4936→
4937→	if (sel_idx == -1)
4938→		return; /* Should never happen */
4939→
4940→	/* Find next/prev client on selected tags */
4941→	if (arg->i > 0) {
4942→		/* Search forward */
4943→		for (i = sel_idx + 1; i < globalconf.clients.len; i++) {
4944→			if (client_on_selected_tags(globalconf.clients.tab[i])) {
4945→				target_idx = i;
4946→				break;
4947→			}
4948→		}
4949→	} else {
4950→		/* Search backward */
4951→		for (i = sel_idx - 1; i >= 0; i--) {
4952→			if (client_on_selected_tags(globalconf.clients.tab[i])) {
4953→				target_idx = i;
4954→				break;
4955→			}
4956→		}
4957→	}
4958→
4959→	if (target_idx == -1)
4960→		return; /* No client found to swap with */
4961→
4962→	/* Swap the two clients in the array */
4963→	tmp = globalconf.clients.tab[sel_idx];
4964→	globalconf.clients.tab[sel_idx] = globalconf.clients.tab[target_idx];
4965→	globalconf.clients.tab[target_idx] = tmp;
4966→
4967→	/* Emit signals (matches AwesomeWM swap()) */
4968→	L = globalconf_get_lua_State();
4969→	if (L) {
4970→		Client *c = globalconf.clients.tab[target_idx]; /* original sel */
4971→		Client *swap = globalconf.clients.tab[sel_idx]; /* original target */
4972→
4973→		luaA_class_emit_signal(L, &client_class, "list", 0);
4974→
4975→		/* First swapped signal on c (is_source=true) */
4976→		luaA_object_push(L, c);
4977→		luaA_object_push(L, swap);
4978→		lua_pushboolean(L, true);
4979→		luaA_object_emit_signal(L, -4, "swapped", 2);
4980→
4981→		/* Second swapped signal on swap (is_source=false) */
4982→		luaA_object_push(L, swap);
4983→		luaA_object_push(L, c);
4984→		lua_pushboolean(L, false);
4985→		luaA_object_emit_signal(L, -3, "swapped", 2);
4986→	}
4987→
4988→	arrange(selmon);
4989→}
