5001→void
5002→togglefloating(const Arg *arg)
5003→{
5004→	Client *sel = focustop(selmon);
5005→	lua_State *L;
5006→	int is_floating;
5007→
5008→	/* return if fullscreen */
5009→	if (!sel || sel->fullscreen)
5010→		return;
5011→
5012→	/* Call Lua to toggle floating: awful.client.floating.toggle(c)
5013→	 * This matches AwesomeWM's approach where C doesn't manage floating state */
5014→	L = globalconf_get_lua_State();
5015→	if (!L)
5016→		return;
5017→
5018→	/* Push client */
5019→	luaA_object_push(L, sel);
5020→
5021→	/* Get current floating state */
5022→	lua_getfield(L, -1, "floating");
5023→	is_floating = lua_toboolean(L, -1);
5024→	lua_pop(L, 1);
5025→
5026→	/* Set new floating state */
5027→	lua_pushboolean(L, !is_floating);
5028→	lua_setfield(L, -2, "floating");
5029→
5030→	lua_pop(L, 1); /* pop client */
5031→}
