5060→void
5061→unmapnotify(struct wl_listener *listener, void *data)
5062→{
5063→	/* Called when the surface is unmapped, and should no longer be shown. */
5064→	Client *c = wl_container_of(listener, c, unmap);
5065→
5066→	/* Safety: If scene was never created (mapnotify failed), nothing to clean up */
5067→	if (!c->scene) {
5068→		return;
5069→	}
5070→
5071→	/* Safety: If Lua destroyed during cleanup, skip Lua-dependent operations */
5072→	if (!globalconf_L) {
5073→		wlr_scene_node_destroy(&c->scene->node);
5074→		return;
5075→	}
5076→
5077→	luaA_emit_signal_global("client::unmap");
5078→
5079→	if (c->toplevel_handle) {
5080→		wl_list_remove(&c->foreign_request_activate.link);
5081→		wl_list_remove(&c->foreign_request_close.link);
5082→		wl_list_remove(&c->foreign_request_fullscreen.link);
5083→		wl_list_remove(&c->foreign_request_maximize.link);
5084→		wl_list_remove(&c->foreign_request_minimize.link);
5085→		wlr_foreign_toplevel_handle_v1_destroy(c->toplevel_handle);
5086→		c->toplevel_handle = NULL;
5087→	}
5088→
5089→	/* CRITICAL: If this is the focused client, clear focus immediately
5090→	 * to prevent client_focus_refresh() from accessing dangling surface pointers */
5091→	if (globalconf.focus.client == c) {
5092→		globalconf.focus.client = NULL;
5093→		globalconf.focus.need_update = true;
5094→	}
5095→
5096→	if (client_is_unmanaged(c)) {
5097→		if (c == exclusive_focus) {
5098→			exclusive_focus = NULL;
5099→			focusclient(focustop(selmon), 1);
5100→		}
5101→	} else {
5102→		/* AwesomeWM pattern: call client_unmanage() from unmapnotify.
5103→		 * This emits request::unmanage while c->screen is still valid,
5104→		 * allowing Lua's check_focus_delayed to restore focus properly.
5105→		 * destroynotify() will see client already removed from array and skip. */
5106→		client_unmanage(c, CLIENT_UNMANAGE_UNMAP);
5107→	}
5108→
5109→	/* Remove commit listener before destroying scene - only registered for XDG clients.
5110→	 * Must be done before surface destruction as wlroots asserts listener lists are empty. */
5111→	if (c->client_type == XDGShell) {
5112→		wl_list_remove(&c->commit.link);
5113→	}
5114→
5115→	wlr_scene_node_destroy(&c->scene->node);
5116→	c->scene = NULL;  /* Mark as cleaned up so destroynotify won't double-remove */
5117→
5118→	/* Clear titlebar scene buffer pointers - they were children of c->scene
5119→	 * and are now freed. Prevents use-after-free in refresh callbacks. */
5120→	for (client_titlebar_t bar = CLIENT_TITLEBAR_TOP; bar < CLIENT_TITLEBAR_COUNT; bar++) {
5121→		c->titlebar[bar].scene_buffer = NULL;
5122→	}
5123→
5124→	printstatus();
5125→	motionnotify(0, NULL, 0, 0, 0, 0);
5126→}
