5128→void
5129→updatemons(struct wl_listener *listener, void *data)
5130→{
5131→	/*
5132→	 * Called whenever the output layout changes: adding or removing a
5133→	 * monitor, changing an output's mode or position, etc. This is where
5134→	 * the change officially happens and we update geometry, window
5135→	 * positions, focus, and the stored configuration in wlroots'
5136→	 * output-manager implementation.
5137→	 */
5138→	/* Guard against re-entrancy: wlr_output_layout_remove/add_auto below
5139→	 * emit layout::change which would call us again, causing
5140→	 * use-after-free in wlroots output_layout_add().
5141→	 * Also used by cleanupmon() to prevent updatemons during output destruction. */
5142→	if (in_updatemons)
5143→		return;
5144→	in_updatemons = 1;
5145→
5146→	struct wlr_output_configuration_v1 *config
5147→			= wlr_output_configuration_v1_create();
5148→	Client *c;
5149→	struct wlr_output_configuration_head_v1 *config_head;
5150→	Monitor *m;
5151→
5152→	/* First remove from the layout the disabled monitors */
5153→	wl_list_for_each(m, &mons, link) {
