 41→static struct wlr_buffer *output_acquire_empty_buffer(struct wlr_output *output,
 42→		const struct wlr_output_state *state) {
 43→	assert(!(state->committed & WLR_OUTPUT_STATE_BUFFER));
 44→
 45→	// wlr_output_configure_primary_swapchain() function will call
 46→	// wlr_output_test_state(), which can call us again. This is dangerous: we
 47→	// risk infinite recursion. However, a buffer will always be supplied in
 48→	// wlr_output_test_state(), which will prevent us from being called.
 49→	if (!wlr_output_configure_primary_swapchain(output, state,
 50→			&output->swapchain)) {
 51→		return NULL;
 52→	}
 53→
 54→	struct wlr_buffer *buffer = wlr_swapchain_acquire(output->swapchain);
 55→	if (buffer == NULL) {
 56→		return NULL;
 57→	}
 58→
 59→	struct wlr_render_pass *pass =
 60→		wlr_renderer_begin_buffer_pass(output->renderer, buffer, NULL);
 61→	if (pass == NULL) {
 62→		wlr_buffer_unlock(buffer);
 63→		return NULL;
 64→	}
 65→
 66→	wlr_render_pass_add_rect(pass, &(struct wlr_render_rect_options){
 67→		.color = { 0, 0, 0, 0 },
 68→		.blend_mode = WLR_RENDER_BLEND_MODE_NONE,
 69→	});
 70→
 71→	if (!wlr_render_pass_submit(pass)) {
 72→		wlr_buffer_unlock(buffer);
 73→		return NULL;
 74→	}
 75→
 76→	return buffer;
 77→}
