 79→// This function may attach a new, empty buffer if necessary.
 80→// If so, the new_back_buffer out parameter will be set to true.
 81→bool output_ensure_buffer(struct wlr_output *output,
 82→		struct wlr_output_state *state, bool *new_buffer) {
 83→	assert(*new_buffer == false);
 84→
 85→	// If we already have a buffer, we don't need to allocate a new one
 86→	if (state->committed & WLR_OUTPUT_STATE_BUFFER) {
 87→		return true;
 88→	}
 89→
 90→	// If the compositor hasn't called wlr_output_init_render(), they will use
 91→	// their own logic to attach buffers
 92→	if (output->renderer == NULL) {
 93→		return true;
 94→	}
 95→
 96→	bool enabled = output->enabled;
 97→	if (state->committed & WLR_OUTPUT_STATE_ENABLED) {
 98→		enabled = state->enabled;
 99→	}
100→
101→	// If we're lighting up an output or changing its mode, make sure to
102→	// provide a new buffer
103→	bool needs_new_buffer = false;
104→	if ((state->committed & WLR_OUTPUT_STATE_ENABLED) && state->enabled) {
105→		needs_new_buffer = true;
106→	}
107→	if (state->committed & WLR_OUTPUT_STATE_MODE) {
108→		needs_new_buffer = true;
109→	}
110→	if (state->committed & WLR_OUTPUT_STATE_RENDER_FORMAT) {
111→		needs_new_buffer = true;
112→	}
113→	if (state->allow_reconfiguration && output->commit_seq == 0 && enabled) {
114→		// On first commit, require a new buffer if the compositor called a
115→		// mode-setting function, even if the mode won't change. This makes it
116→		// so the swapchain is created now.
117→		needs_new_buffer = true;
118→	}
119→	if (!needs_new_buffer) {
120→		return true;
121→	}
122→
123→	wlr_log(WLR_DEBUG, "Attaching empty buffer to output for modeset");
124→	struct wlr_buffer *buffer = output_acquire_empty_buffer(output, state);
125→	if (buffer == NULL) {
126→		return false;
127→	}
128→
129→	*new_buffer = true;
130→	wlr_output_state_set_buffer(state, buffer);
131→	wlr_buffer_unlock(buffer);
132→	return true;
133→}
