147→bool output_pick_format(struct wlr_output *output,
148→		const struct wlr_drm_format_set *display_formats,
149→		struct wlr_drm_format *format, uint32_t fmt) {
150→	struct wlr_renderer *renderer = output->renderer;
151→	struct wlr_allocator *allocator = output->allocator;
152→	assert(renderer != NULL && allocator != NULL);
153→
154→	const struct wlr_drm_format_set *render_formats =
155→		wlr_renderer_get_render_formats(renderer);
156→	if (render_formats == NULL) {
157→		wlr_log(WLR_ERROR, "Failed to get render formats");
158→		return false;
159→	}
160→
161→	const struct wlr_drm_format *render_format =
162→		wlr_drm_format_set_get(render_formats, fmt);
163→	if (render_format == NULL) {
164→		wlr_log(WLR_DEBUG, "Renderer doesn't support format 0x%"PRIX32, fmt);
165→		return false;
166→	}
167→
168→	if (display_formats != NULL) {
169→		const struct wlr_drm_format *display_format =
170→			wlr_drm_format_set_get(display_formats, fmt);
171→		if (display_format == NULL) {
172→			wlr_log(WLR_DEBUG, "Output doesn't support format 0x%"PRIX32, fmt);
173→			return false;
174→		}
175→		if (!wlr_drm_format_intersect(format, display_format, render_format)) {
176→			wlr_log(WLR_DEBUG, "Failed to intersect display and render "
177→				"modifiers for format 0x%"PRIX32 " on output %s",
178→				fmt, output->name);
179→			return false;
180→		}
181→	} else {
182→		// The output can display any format
183→		if (!wlr_drm_format_copy(format, render_format)) {
184→			return false;
185→		}
186→	}
187→
188→	if (format->len == 0) {
189→		wlr_drm_format_finish(format);
190→		wlr_log(WLR_DEBUG, "Failed to pick output format");
191→		return false;
192→	}
193→
194→	return true;
195→}
