197→struct wlr_render_pass *wlr_output_begin_render_pass(struct wlr_output *output,
198→		struct wlr_output_state *state, struct wlr_buffer_pass_options *render_options) {
199→	if (!wlr_output_configure_primary_swapchain(output, state, &output->swapchain)) {
200→		return NULL;
201→	}
202→
203→	struct wlr_buffer *buffer = wlr_swapchain_acquire(output->swapchain);
204→	if (buffer == NULL) {
205→		return NULL;
206→	}
207→
208→	struct wlr_renderer *renderer = output->renderer;
209→	assert(renderer != NULL);
210→	struct wlr_render_pass *pass = wlr_renderer_begin_buffer_pass(renderer, buffer, render_options);
211→	if (pass == NULL) {
212→		return NULL;
213→	}
214→
215→	wlr_output_state_set_buffer(state, buffer);
216→	wlr_buffer_unlock(buffer);
217→	return pass;
218→}
