/* Cold restart: after clean shutdown, exec self for a fresh start.
 * All wlroots resources (DRM master, sockets) released by cleanup(). */
if (globalconf.restart_pending) {
	signal(SIGINT, SIG_DFL);
	signal(SIGTERM, SIG_DFL);
	signal(SIGCHLD, SIG_DFL);
	execvp(globalconf.argv[0], globalconf.argv);
	fprintf(stderr, "cold_restart: execvp(%s) failed: %s\n",
	        globalconf.argv[0], strerror(errno));
	return EXIT_FAILURE;
}

