5891→/* Get distro name from /etc/os-release */
5892→static const char *
5893→get_distro_name(void)
5894→{
5895→	static char distro[256] = "unknown";
5896→	char line[256];
5897→	FILE *f;
5898→
5899→	f = fopen("/etc/os-release", "r");
5900→	if (!f)
5901→		return distro;
5902→
5903→	while (fgets(line, sizeof(line), f)) {
5904→		if (strncmp(line, "PRETTY_NAME=", 12) == 0) {
5905→			char *start = line + 12;
5906→			size_t len;
5907→			/* Strip leading quote */
5908→			if (*start == '"') start++;
5909→			len = strlen(start);
5910→			/* Strip trailing newline and quote */
5911→			while (len > 0 && (start[len-1] == '\n' || start[len-1] == '"'))
5912→				start[--len] = '\0';
5913→			strncpy(distro, start, sizeof(distro) - 1);
5914→			distro[sizeof(distro) - 1] = '\0';
5915→			break;
5916→		}
5917→	}
5918→	fclose(f);
5919→	return distro;
5920→}
