5922→/* Get GPU info from /sys/class/drm */
5923→static const char *
5924→get_gpu_info(void)
5925→{
5926→	static char gpu[256] = "unknown";
5927→	char path[64];
5928→	char line[128];
5929→	char driver[64] = "";
5930→	char pci_id[32] = "";
5931→	FILE *f;
5932→	int i;
5933→
5934→	/* Try card0, card1, etc. */
5935→	for (i = 0; i < 4; i++) {
5936→		snprintf(path, sizeof(path), "/sys/class/drm/card%d/device/uevent", i);
5937→		f = fopen(path, "r");
5938→		if (!f)
5939→			continue;
5940→
5941→		while (fgets(line, sizeof(line), f)) {
5942→			if (strncmp(line, "DRIVER=", 7) == 0) {
5943→				char *start = line + 7;
5944→				size_t len = strlen(start);
5945→				if (len > 0 && start[len-1] == '\n')
5946→					start[len-1] = '\0';
5947→				strncpy(driver, start, sizeof(driver) - 1);
5948→				driver[sizeof(driver) - 1] = '\0';
5949→			} else if (strncmp(line, "PCI_ID=", 7) == 0) {
5950→				char *start = line + 7;
5951→				size_t len = strlen(start);
5952→				if (len > 0 && start[len-1] == '\n')
5953→					start[len-1] = '\0';
5954→				strncpy(pci_id, start, sizeof(pci_id) - 1);
5955→				pci_id[sizeof(pci_id) - 1] = '\0';
5956→			}
5957→		}
5958→		fclose(f);
5959→
5960→		if (driver[0]) {
5961→			snprintf(gpu, sizeof(gpu), "%s%s%s%s", driver,
5962→				pci_id[0] ? " (" : "", pci_id,
5963→				pci_id[0] ? ")" : "");
5964→			break;
5965→		}
5966→	}
5967→	return gpu;
5968→}
