5970→/* Get Lua runtime version string */
5971→static const char *
5972→get_lua_runtime_version(lua_State *L)
5973→{
5974→	static char version[128];
5975→
5976→	/* Check for LuaJIT first */
5977→	lua_getglobal(L, "jit");
5978→	if (lua_istable(L, -1)) {
5979→		lua_getfield(L, -1, "version");
5980→		if (lua_isstring(L, -1)) {
5981→			snprintf(version, sizeof(version), "%s", lua_tostring(L, -1));
5982→			lua_pop(L, 2);
5983→			return version;
5984→		}
5985→		lua_pop(L, 1);
5986→	}
5987→	lua_pop(L, 1);
5988→
5989→	/* Fall back to standard Lua _VERSION */
5990→	lua_getglobal(L, "_VERSION");
5991→	if (lua_isstring(L, -1)) {
5992→		snprintf(version, sizeof(version), "%s", lua_tostring(L, -1));
5993→	} else {
5994→		snprintf(version, sizeof(version), "unknown");
5995→	}
5996→	lua_pop(L, 1);
5997→	return version;
5998→}
