6023→/* Add search paths to a Lua state's package.path and package.cpath */
6024→static void
6025→add_search_paths_to_lua(lua_State *L, const char **paths, int count)
6026→{
6027→	const char *cur_path;
6028→
6029→	for (int i = 0; i < count; i++) {
6030→		const char *dir = paths[i];
6031→
6032→		/* Add to package.path */
6033→		lua_getglobal(L, "package");
6034→		lua_getfield(L, -1, "path");
6035→		cur_path = lua_tostring(L, -1);
6036→		lua_pop(L, 1);
6037→		lua_pushfstring(L, "%s/?.lua;%s/?/init.lua;%s", dir, dir, cur_path);
6038→		lua_setfield(L, -2, "path");
6039→
6040→		/* Add to package.cpath */
6041→		lua_getfield(L, -1, "cpath");
6042→		cur_path = lua_tostring(L, -1);
6043→		lua_pop(L, 1);
6044→		lua_pushfstring(L, "%s/?.so;%s", dir, cur_path);
6045→		lua_setfield(L, -2, "cpath");
6046→
6047→		lua_pop(L, 1); /* pop package table */
6048→	}
6049→}
