6112→int
6113→main(int argc, char *argv[])
6114→{
6115→	char *startup_cmd = NULL;
6116→	char *check_config = NULL;
6117→	int show_version = 0;
6118→	int c;
6119→
6120→	/* Store argv for restart capability (AwesomeWM API parity) */
6121→	globalconf.argc = argc;
6122→	globalconf.argv = argv;
6123→
6124→	static struct option long_options[] = {
6125→		{"help",    no_argument,       0, 'h'},
6126→		{"version", no_argument,       0, 'v'},
6127→		{"verbose", no_argument,       0, 256},  /* info-level logging */
6128→		{"debug",   no_argument,       0, 'd'},
6129→		{"config",  required_argument, 0, 'c'},
6130→		{"search",  required_argument, 0, 'L'},
6131→		{"startup", required_argument, 0, 's'},
6132→		{"check",   required_argument, 0, 'k'},
6133→		{0, 0, 0, 0}
6134→	};
6135→
6136→	while ((c = getopt_long(argc, argv, "c:s:L:hdvk:", long_options, NULL)) != -1) {
6137→		switch (c) {
6138→		case 'c':
6139→			luaA_set_confpath(optarg);
6140→			break;
6141→		case 's':
6142→			startup_cmd = optarg;
6143→			break;
6144→		case 'k':
6145→			check_config = optarg;
6146→			break;
6147→		case 'L':
6148→			if (num_search_paths < MAX_SEARCH_PATHS) {
6149→				search_paths[num_search_paths++] = optarg;
6150→			} else {
6151→				fprintf(stderr, "Warning: too many search paths, ignoring %s\n", optarg);
6152→			}
6153→			break;
6154→		case 'd':
6155→			globalconf.log_level = 3;  /* WLR_DEBUG */
6156→			break;
6157→		case 256:  /* --verbose */
6158→			globalconf.log_level = 2;  /* WLR_INFO */
6159→			break;
6160→		case 'v':
6161→			show_version = 1;
6162→			break;
6163→		default:
6164→			goto usage;
6165→		}
6166→	}
6167→	if (optind < argc)
6168→		goto usage;
6169→
6170→	/* Show version after all args parsed so -L paths are available */
6171→	if (show_version)
6172→		print_version_info(search_paths, num_search_paths);
6173→
6174→	/* Check mode: scan config for compatibility issues without starting compositor */
6175→	if (check_config) {
6176→		bool use_color = isatty(STDOUT_FILENO);
6177→		int result = luaA_check_config(check_config, use_color);
6178→		return result;
6179→	}
6180→
6181→	/* Wayland requires XDG_RUNTIME_DIR for creating its communications socket */
6182→	if (!getenv("XDG_RUNTIME_DIR"))
6183→		die("XDG_RUNTIME_DIR must be set");
6184→
6185→	/* Pass search paths to Lua init */
6186→	if (num_search_paths > 0)
6187→		luaA_add_search_paths(search_paths, num_search_paths);
6188→
6189→	setup();
6190→	run(startup_cmd);
6191→
6192→	/* Save restart state before cleanup — cleanup() calls globalconf_wipe()
6193→	 * which zeroes restart_pending and argv. */
6194→	bool do_restart = globalconf.restart_pending;
6195→	char **restart_argv = globalconf.argv;
6196→
6197→	cleanup();
6198→
6199→	/* Cold restart: after clean shutdown, exec self for a fresh start.
6200→	 * All wlroots resources (DRM master, sockets) released by cleanup(). */
6201→	if (do_restart) {
6202→		signal(SIGINT, SIG_DFL);
6203→		signal(SIGTERM, SIG_DFL);
6204→		signal(SIGCHLD, SIG_DFL);
6205→		execvp(restart_argv[0], restart_argv);
6206→		fprintf(stderr, "cold_restart: execvp(%s) failed: %s\n",
6207→		        restart_argv[0], strerror(errno));
6208→		return EXIT_FAILURE;
6209→	}
6210→
6211→	return EXIT_SUCCESS;
6212→
6213→usage:
6214→	die("Usage: %s [-v] [-d] [--verbose] [-c config] [-L search_path] [-s startup_command] [-k config]\n"
6215→	    "  -v, --version      Show version and diagnostic info\n"
6216→	    "      --verbose      Enable info-level logging (more output)\n"
6217→	    "  -d, --debug        Enable debug logging (maximum output)\n"
6218→	    "  -c, --config FILE  Use specified config file (AwesomeWM compatible)\n"
6219→	    "  -L, --search DIR   Add directory to Lua module search path\n"
6220→	    "  -s, --startup CMD  Run command after startup\n"
6221→	    "  -k, --check CONFIG Check config for Wayland compatibility issues", argv[0]);
6222→}
